/* ---------- Context meter ---------- */
.ctm{display:flex;flex-direction:column;align-items:flex-end;gap:10px;width:100%;max-width:330px;margin-inline:auto}
.ctm-pop{width:100%;padding:14px 16px 16px;border-radius:16px;box-shadow:var(--shadow-pop);transform-origin:bottom right;transition:opacity .25s var(--ease),transform .4s var(--ease),filter .25s}
.ctm.shut .ctm-pop{opacity:0;transform:translateY(6px) scale(.98);filter:blur(3px);pointer-events:none}
.ctm-ph{display:flex;align-items:center;justify-content:space-between;margin:-4px -6px 8px 0}
.ctm-ph b{font-size:15px;font-weight:600}
.ctm-ib{width:28px;height:28px;color:var(--fg2)}
.ctm-rows{display:flex;flex-direction:column;gap:16px}
.ctm-r{display:grid;grid-template-columns:1fr auto;align-items:baseline;row-gap:8px}
.ctm-r .l{font-size:13.5px;font-weight:500}
.ctm-r .p{font-size:12.5px;color:var(--muted)}
.ctm-tr{grid-column:1/-1;height:6px;border-radius:3px;background:var(--chip);overflow:hidden}
.ctm-tr i{display:block;height:100%;width:0;border-radius:inherit;background:var(--accent);transition:width 1s var(--ease),background .3s}
.ctm-r.hot .ctm-tr i{background:var(--warn)}
.ctm-r .s{grid-column:1/-1;display:flex;align-items:center;gap:8px;min-height:20px;margin-top:-2px;font-size:12.5px;color:var(--muted)}
.ctm-go{margin-left:auto;height:24px;padding:0 9px;border-radius:7px;font-size:12px;font-weight:500;color:var(--fg);background:var(--soft,var(--chip));box-shadow:var(--soft-ring,none);transition:background var(--t-fast)}
.ctm-go:hover{background:var(--soft-h,var(--hover))}
.ctm-ft{display:flex;align-items:center;gap:8px;font-size:13px;color:var(--fg2)}
.ctm-ft .muted{margin-right:2px}
.ctm-ring{width:30px;height:30px;border-radius:9px;display:grid;place-items:center;transition:background var(--t-fast)}
.ctm-ring:hover,.ctm-ring[aria-expanded="true"]{background:var(--chip)}
.ctm-ring svg{width:18px;height:18px;transform:rotate(-90deg);overflow:visible}
.ctm-ring circle{fill:none;stroke-width:2.6}
.ctm-ring .tr{stroke:var(--rail)}
.ctm-ring .fl{stroke:var(--accent);stroke-linecap:round;stroke-dasharray:0 100;transition:stroke-dasharray 1s var(--ease),stroke .3s}

DM.def('context-meter', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{bars}', I('bars'));
  /* the context window first, then the plan limits; the ring shows how full the context is */
  const ROWS = [
    { k:'ctx', l:'Context window', v:68, s:'136k of 200k tokens', tip:'Files 56k · Conversation 60k · Tool results 20k', go:'Compact' },
    { k:'ses', l:'Session limit', v:4, s:'Resets in 4 hr 39 min' },
    { k:'wk', l:'Weekly', v:16, s:'Resets Sun 10:00 PM' }
  ];
  const root = $('.ctm', r), rows = $('.ctm-rows', r), ring = $('.ctm-ring', r), arc = $('.ctm-ring .fl', r);
  rows.innerHTML = ROWS.map(x => `<div class="ctm-r" data-k="${x.k}"><span class="l">${x.l}</span><span class="p num"><b style="font-weight:inherit">0</b>% used</span><span class="ctm-tr" role="meter" aria-label="${x.l}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="0"${x.tip ? ` data-tip="${x.tip}"` : ''}><i></i></span><span class="s"><span class="t">${x.s}</span>${x.go ? `<button class="ctm-go">${x.go}</button>` : ''}</span></div>`).join('');
  const shown = {};
  function set(k, v){
    const row = $(`.ctm-r[data-k="${k}"]`, rows), n = $('.p b', row), from = shown[k] || 0; shown[k] = v;
    $('.ctm-tr i', row).style.width = v + '%'; $('.ctm-tr', row).setAttribute('aria-valuenow', v); row.classList.toggle('hot', v >= 90);
    tween(from, v, 1000, x => n.textContent = Math.round(x));
    if (k === 'ctx'){ arc.style.strokeDasharray = v + ' 100'; arc.style.stroke = v >= 90 ? 'var(--warn)' : ''; ring.setAttribute('aria-label', 'Usage, context ' + v + '% full'); }
  }
  ring.onclick = () => { const open = root.classList.toggle('shut') === false; ring.setAttribute('aria-expanded', open); };
  /* compacting frees most of the context, Undo puts the full thread back */
  const go = $('.ctm-go', rows), sub = $('.ctm-r[data-k="ctx"] .t', rows); let compacted = false;
  go.onclick = () => c.run(async () => {
    if (go._busy) return; go._busy = true;
    if (!compacted){ swap(go, 'Compacting'); swap(sub, 'Summarising the thread'); await c.wait(900); set('ctx', 38); swap(sub, '76k of 200k tokens, 9 decisions kept'); swap(go, 'Undo'); }
    else { set('ctx', 68); swap(sub, '136k of 200k tokens'); swap(go, 'Compact'); }
    compacted = !compacted; go._busy = false;
  });
  c.later(300, () => ROWS.forEach(x => set(x.k, x.v)));
});
